import java.nio.file.*;import java.util.*;import com.google.gson.*;import io.johnsonlee.graphite.cypher.*;import io.johnsonlee.graphite.graph.*;import io.johnsonlee.graphite.webgraph.*;
public class TupleCacheOracle{
 public static void main(String[]args)throws Exception{
  Graph g=GraphStore.INSTANCE.loadMapped(Path.of(args[0]));var e=new CypherExecutor(g);e.execute("MATCH (n) WHERE n.caller_name CONTAINS 'other' RETURN DISTINCT n.caller_name AS x LIMIT 1");Object i=ExactTupleOracle.field(g,"callSiteStringIndex");ExactTupleOracle.call(i,"clearQueryCaches",new Class<?>[0]);var out=new LinkedHashMap<String,Object>();var cols=new ArrayList<String>();for(int n=0;n<68;n++)cols.add("n.caller_name AS x"+n);String q="MATCH (n) WHERE n.caller_name CONTAINS 'other' RETURN "+String.join(",",cols)+" LIMIT 200";out.put("query",q);var result=e.execute(q);out.put("columns",result.getColumns());out.put("rows",result.getRows());out.put("before",ExactTupleOracle.state(i));out.put("serialBefore",ExactTupleOracle.call(i,"getPrefersSerialScan",new Class<?>[0]));Set<List<String>> values=new LinkedHashSet<>();for(int n=0;n<256;n++)values.add(List.of("other"+n));ExactTupleOracle.call(i,"distinctProjection",new Class<?>[]{List.class,List.class,int.class,Set.class,GraphWorkConsumer.class},ExactTupleOracle.PS,List.of("caller_name"),256,values,null);out.put("after",ExactTupleOracle.state(i));out.put("serialAfter",ExactTupleOracle.call(i,"getPrefersSerialScan",new Class<?>[0]));ExactTupleOracle.call(i,"clearQueryCaches",new Class<?>[0]);out.put("cleared",ExactTupleOracle.state(i));out.put("serialCleared",ExactTupleOracle.call(i,"getPrefersSerialScan",new Class<?>[0]));((java.io.Closeable)g).close();Files.writeString(Path.of(args[1]),new GsonBuilder().serializeNulls().setPrettyPrinting().create().toJson(out)+"\n");
 }
}
